// n8n Code 节点：Build LLM Request Body
// 输入：Postgres 返回的一条 video_topics 记录
// 输出：保留原始字段，并新增 llm_request_body，供 HTTP Request 调用 OpenAI-compatible /v1/chat/completions。

const item = $input.first().json;

const systemPrompt = `你是一个专业短视频编导、内容运营和平台风控助手。你的任务是生成可执行的短视频脚本包。必须只输出严格 JSON。`;

const userPrompt = `
你是一个短视频编导与运营，请根据数据库里的选题生成一个“短视频脚本包”。

输入字段：
- 选题：${item.topic}
- 平台：${item.platform}
- 风格：${item.style}
- 目标时长：${item.duration_seconds} 秒
- 语言：${item.language || 'zh-CN'}
- 目标用户：${item.target_audience || '普通短视频用户'}

要求：
1. 只输出严格 JSON，不要输出 Markdown，不要输出解释。
2. 文案必须适合短视频口播，前 3 秒要有强钩子。
3. 标题不要过度标题党，不要承诺收益，不要虚假夸大。
4. 分镜 shots 的 duration 总和尽量接近目标时长。
5. hashtags 输出数组，不要带 # 号。
6. 如存在风险，在 risk_check.notes 里提醒人工审核。
7. 每个 shot 必须同时服务“口播”和“Remotion 动态版式”：subtitle/body 保持完整口播语义，headline 是画面主标题，keywords 是 1-4 个短关键词，layout_hint 是给版式的简短节奏提示。
8. template_type 必须从 knowledge、list、contrast、story 中选择，不能输出其他值。选择依据：
   - knowledge：概念解释、方法论、科普知识、观点展开；如果内容没有明显步骤、对比或故事线，默认选它。
   - list：三步法、清单、避坑、操作流程、编号建议；脚本里出现第一/第二/第三、几个方法、步骤时优先选它。
   - contrast：误区 vs 正解、前后对比、反常识观点、纠偏类内容；脚本里出现不是/而是、误区、真正、对比时优先选它。
   - story：个人经历、案例、转折叙事、时间推进；脚本里有起因/经过/转折/结果时优先选它。
9. template_type 决定 Remotion 动态版式：knowledge=概念解释卡，list=步骤编号卡，contrast=误区/正解双栏，story=时间线叙事卡。

输出 JSON 结构如下：
{
  "title": "短视频标题",
  "hook": "前3秒钩子",
  "script": "完整口播脚本，分段清晰",
  "cover_text": "封面大字，不超过12个汉字",
  "template_type": "knowledge",
  "hashtags": ["标签1", "标签2", "标签3"],
  "shots": [
    {
      "shot_id": 1,
      "duration": 5,
      "headline": "画面主标题，建议6到18个汉字",
      "body": "完整正文，用于画面中部说明，语义必须和subtitle一致",
      "keywords": ["关键词1", "关键词2", "关键词3"],
      "layout_hint": "例如：强调反差 / 步骤推进 / 结论收束，不超过16个汉字",
      "visual_prompt_cn": "中文封面或画面氛围提示词，不要包含文字水印要求",
      "visual_prompt_en": "英文画面提示词",
      "subtitle": "这一段完整口播字幕"
    }
  ],
  "risk_check": {
    "copyright_risk": "低/中/高",
    "sensitive_risk": "低/中/高",
    "factual_risk": "低/中/高",
    "notes": "需要人工注意的点"
  }
}
`;

return [
  {
    json: {
      ...item,
      llm_request_body: {
        model: "glm-5.1",
        temperature: 0.7,
        max_tokens: 8000,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPrompt }
        ]
      }
    }
  }
];

// n8n Code 节点：Parse LLM Response
// 作用：兼容 OpenAI-compatible HTTP Response / n8n AI 节点的常见输出格式，解析 JSON，并整理成 Postgres 更新字段。

function extractText(json) {
  if (!json || typeof json !== 'object') return '';

  // 如果 HTTP Request 使用了 “Put Response in Field = llm_response”
  if (json.llm_response?.choices?.[0]?.message?.content) {
    return json.llm_response.choices[0].message.content;
  }

  // OpenAI-compatible 原始响应
  if (json.choices?.[0]?.message?.content) {
    return json.choices[0].message.content;
  }

  // 一些 n8n AI / LLM 节点常见字段
  if (typeof json.output === 'string') return json.output;
  if (typeof json.text === 'string') return json.text;
  if (typeof json.response === 'string') return json.response;
  if (typeof json.message?.content === 'string') return json.message.content;

  // 万不得已：尝试把整个对象当作文本解析
  return JSON.stringify(json);
}

function cleanJsonText(text) {
  let s = String(text || '').trim();
  s = s.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

  // 如果模型输出前后有废话，截取第一个 { 到最后一个 }
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start >= 0 && end > start) {
    s = s.slice(start, end + 1);
  }
  return s;
}

const input = $input.first().json;
const source = $('Postgres - Mark GENERATING_SCRIPT').first().json;
const raw = extractText(input);
const cleaned = cleanJsonText(raw);

let data;
try {
  data = JSON.parse(cleaned);
} catch (err) {
  throw new Error(`LLM 输出不是合法 JSON：${err.message}\n原始输出：${raw.slice(0, 1000)}`);
}

const hashtags = Array.isArray(data.hashtags) ? data.hashtags : [];
const shots = Array.isArray(data.shots) ? data.shots : [];
const templateType = ['knowledge', 'list', 'contrast', 'story'].includes(data.template_type) ? data.template_type : 'knowledge';
const riskCheck = data.risk_check && typeof data.risk_check === 'object' ? data.risk_check : {};

return [
  {
    json: {
      id: source.id,
      topic: source.topic,
      platform: source.platform,
      style: source.style,
      duration_seconds: source.duration_seconds,
      title: data.title || '',
      hook: data.hook || '',
      script: data.script || '',
      cover_text: data.cover_text || '',
      hashtags,
      hashtags_json: JSON.stringify(hashtags),
      shots,
      shots_json: JSON.stringify(shots),
      template_type: templateType,
      risk_check: riskCheck,
      risk_check_json: JSON.stringify(riskCheck),
      status: 'SCRIPT_READY',
      updated_at: new Date().toISOString()
    }
  }
];

/**
 * n8n Code node: Build Render Request Remotion
 * Input: one row from PostgreSQL video_topics.
 * Output: JSON body for POST http://video-worker:8000/render
 */

const row = $json;
const id = String(row.id || '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) {
  throw new Error(`No SCRIPT_READY video topic was claimed. Upstream Postgres row is missing a valid uuid id: ${JSON.stringify(row).slice(0, 1000)}`);
}

function parseJsonMaybe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return fallback;
  }
}

let shots = parseJsonMaybe(row.shots_json, []);
if (!Array.isArray(shots) || shots.length === 0) {
  shots = [
    {
      shot_id: 1,
      duration: Number(row.duration || row.duration_seconds || 8),
      subtitle: row.hook || row.cover_text || row.title || row.topic,
      visual_prompt_cn: row.cover_text || row.title || row.topic,
    },
  ];
}

shots = shots.map((shot, index) => ({
  shot_id: shot.shot_id ?? index + 1,
  duration: Number(shot.duration || 5),
  subtitle: String(shot.subtitle || ''),
  headline: String(shot.headline || ''),
  body: String(shot.body || shot.subtitle || ''),
  keywords: Array.isArray(shot.keywords) ? shot.keywords.map((item) => String(item).trim()).filter(Boolean).slice(0, 4) : [],
  layout_hint: String(shot.layout_hint || ''),
  visual_prompt_cn: String(shot.visual_prompt_cn || shot.prompt || shot.subtitle || ''),
  visual_prompt_en: String(shot.visual_prompt_en || ''),
}));

const title = String(row.title || row.topic || 'AI 短视频');
const coverText = String(row.cover_text || row.title || row.topic || '');
const templateType = String(row.template_type || row.remotion_template_type || 'knowledge');

return [
  {
    json: {
      task_id: id,
      title,
      script: String(row.script || row.hook || row.topic || ''),
      cover_text: coverText,
      platform: String(row.platform || 'default'),
      cover_prompt: `竖屏短视频封面背景，主题：${title}，封面文案参考：${coverText}，画面主体明确，留出上方标题空间，不要生成文字，不要logo，不要水印，商业短视频封面质感`,
      shots,
      width: 1080,
      height: 1920,
      fps: 30,

      enable_tts: true,
      tts_base_url: 'http://host.docker.internal:8010',

      enable_comfyui: true,
      comfyui_mode: 'cover_only',
      comfyui_options: {
        base_url: 'http://host.docker.internal:8000',
        workflow_template_path: '/app/comfyui/zimage_text2image_api_template.json',
        prompt_node_id: '63',
        save_node_id: '9',
        sampler_node_id: '57:3',
        latent_node_id: '57:13',
        filename_prefix: 'n8n-video',
        image_width: 720,
        image_height: 1280,
        timeout_seconds: 900,
        poll_interval_seconds: 2,
        fallback_to_placeholder: true,
        overlay_cover_text: true,
        prompt_prefix: '竖屏短视频封面主视觉，真实摄影，电影感光影，构图干净，手机竖屏，高清细节',
        negative_prompt: '多个人，过度锐化，塑料质感，畸形手指，多余的手，畸形肢体，文字乱码，logo，水印，低清晰度，模糊',
      },

      render_engine: 'remotion',
      template_type: templateType,
      remotion_renderer_url: 'http://host.docker.internal:3001',
    },
  },
];

/**
 * n8n Code node: Parse Render Response Remotion
 * Input: JSON returned by video-worker.
 * Output: fields used by PostgreSQL update query.
 */

const data = $json;

if (!data || data.status !== 'ok') {
  throw new Error(`Render failed or invalid response: ${JSON.stringify(data).slice(0, 1000)}`);
}

return [
