      media_manifest: JSON.stringify(data.media_manifest || {}),
      comfyui_prompt_ids: JSON.stringify(data.comfyui_prompt_ids || {}),
    },
  },
];

/**
 * n8n Code 节点：Build Render Request
 * 输入：Postgres - Claim One SCRIPT_READY 的单条记录
 * 输出：给 video-worker /render 的请求体
 */

function safeJson(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return fallback;
  }
}

const item = $input.first().json;

if (!item.id) {
  throw new Error('没有拿到任务 id。请确认 Postgres Claim 节点有返回 SCRIPT_READY 任务。');
}

const hashtags = safeJson(item.hashtags, []);
const shots = safeJson(item.shots_json, []);
const riskCheck = safeJson(item.risk_check, {});

const body = {
  task_id: item.id,
  topic: item.topic || '',
  platform: item.platform || 'youtube',
  style: item.style || '口播科普',
  duration_seconds: Number(item.duration_seconds || 45),
  language: item.language || 'zh-CN',
  title: item.title || item.topic || '未命名视频',
  hook: item.hook || '',
  script: item.script || '',
  cover_text: item.cover_text || item.title || item.topic || '短视频',
  hashtags,
  shots,
  risk_check: riskCheck,
  // 第二版先用 Worker 内置封面生成，后面你可以改成 comfyui_cover_path
  cover_image_path: item.cover_path || null
};

return [
  {
    json: {
      id: item.id,
      render_url: 'http://video-worker:8000/render',
      body
    }
  }
];

/**
 * n8n Code 节点：Parse Render Response
 * 输入：HTTP Request - Render Video 的响应 JSON
 * 输出：Postgres Update NEED_REVIEW 需要的字段
 */

const response = $input.first().json;

if (!response || response.status !== 'ok') {
  const message = response?.error || response?.message || 'video-worker 未返回 ok 状态';
  throw new Error(message);
}

if (!response.task_id) {
  throw new Error('video-worker 响应缺少 task_id');
}

if (!response.video_path) {
  throw new Error('video-worker 响应缺少 video_path');
}

const renderResult = {
  worker_status: response.status,
  task_id: response.task_id,
  cover_path: response.cover_path || null,
  video_path: response.video_path,
  subtitle_path: response.subtitle_path || null,
  manifest_path: response.manifest_path || null,
  rendered_at: new Date().toISOString()
};

return [
  {
    json: {
      id: response.task_id,
      cover_path: response.cover_path || null,
      video_path: response.video_path,
      subtitle_path: response.subtitle_path || null,
      manifest_path: response.manifest_path || null,
      render_result: renderResult,
      render_result_json: JSON.stringify(renderResult)
    }
  }
];

/**
 * n8n Code node: Build Render Request ComfyUI
 * Input: one row from PostgreSQL video_topics.
 * Output: JSON body for POST http://video-worker:8000/render
 */

const row = $json;

function parseJsonMaybe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return fallback;
  }
}

let shots = parseJsonMaybe(row.shots_json, []);
if (!Array.isArray(shots) || shots.length === 0) {
  shots = [
    {
      shot_id: 1,
      duration: Number(row.duration || 8),
      subtitle: row.hook || row.cover_text || row.title || row.topic,
      visual_prompt_cn: row.cover_text || row.title || row.topic,
    },
