shots = shots.map((shot, index) => ({
  shot_id: shot.shot_id ?? index + 1,
  duration: Number(shot.duration || 5),
  subtitle: String(shot.subtitle || ''),
  visual_prompt_cn: String(shot.visual_prompt_cn || shot.prompt || shot.subtitle || ''),
  visual_prompt_en: String(shot.visual_prompt_en || ''),
}));

const title = String(row.title || row.topic || 'AI 短视频');
const coverText = String(row.cover_text || row.title || row.topic || '');

return [
  {
    json: {
      task_id: String(row.id),
      title,
      script: String(row.script || row.hook || row.topic || ''),
      cover_text: coverText,
      cover_prompt: `竖屏短视频封面背景，主题：${title}，封面文案参考：${coverText}，画面主体明确，留出上方标题空间，不要生成文字，不要logo，不要水印，商业短视频封面质感`,
      shots,
      width: 1080,
      height: 1920,
      fps: 30,

      enable_tts: true,
      tts_base_url: 'http://host.docker.internal:8010',

      enable_comfyui: true,
      comfyui_options: {
        base_url: 'http://host.docker.internal:8000',
        workflow_template_path: '/app/comfyui/zimage_text2image_api_template.json',
        prompt_node_id: '63',
        save_node_id: '9',
        sampler_node_id: '57:3',
        latent_node_id: '57:13',
        filename_prefix: 'n8n-video',
        image_width: 720,
        image_height: 1280,
        timeout_seconds: 900,
        poll_interval_seconds: 2,
        fallback_to_placeholder: true,
        overlay_cover_text: true,
        prompt_prefix: '竖屏短视频画面，真实摄影，电影感光影，构图干净，手机竖屏，高清细节',
        negative_prompt: '多个人，过度锐化，塑料质感，畸形手指，多余的手，畸形肢体，文字乱码，logo，水印，低清晰度，模糊',
      },
    },
  },
];

/**
 * n8n Code node: Parse Render Response ComfyUI
 * Input: JSON returned by video-worker v0.4.0.
 * Output: fields used by PostgreSQL update query.
 */

const data = $json;

if (!data || data.status !== 'ok') {
  throw new Error(`Render failed or invalid response: ${JSON.stringify(data).slice(0, 1000)}`);
}

return [
  {
    json: {
      task_id: data.task_id,
      video_path: data.video_path,
      cover_path: data.cover_path || null,
      subtitle_path: data.subtitle_path || null,
      clips_json: JSON.stringify(data.clips || []),
      render_manifest: JSON.stringify(data),
      voice_path: data.voice_path || null,
      audio_duration: Number(data.audio_duration || 0),
      audio_engine: data.audio_engine || 'VoxCPM',
      shot_images_json: JSON.stringify(data.images || []),
      media_engine: data.media_engine || 'ComfyUI',
      media_manifest: JSON.stringify(data.media_manifest || {}),
      comfyui_prompt_ids: JSON.stringify(data.comfyui_prompt_ids || {}),
    },
  },
];

/**
 * n8n Code 节点：Build Render Request Enhanced
 * 输入：Postgres - Claim One SCRIPT_READY 返回的 video_topics 行
 * 输出：给 video-worker /render 的请求体
 */

function parseJsonLoose(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return fallback;
  try {
    return JSON.parse(value);
  } catch (err) {
    return fallback;
  }
}

function fallbackShotsFromScript(script, defaultDuration) {
  const text = String(script || '').trim();
  if (!text) {
    return [
      {
        shot_id: 1,
        duration: defaultDuration,
        visual_prompt_cn: '简洁竖屏短视频背景，标题居中，适合知识口播',
        subtitle: '这里是自动生成的测试分镜。'
      }
    ];
  }

  const parts = text
    .split(/[\n。！？!?]+/)
    .map(s => s.trim())
    .filter(Boolean)
    .slice(0, 8);

  return parts.map((line, index) => ({
    shot_id: index + 1,
    duration: defaultDuration,
    visual_prompt_cn: `竖屏短视频第 ${index + 1} 个分镜，画面服务于这句口播：${line}`,
    subtitle: line
  }));
}

function normalizeHashtags(value) {
  const parsed = parseJsonLoose(value, value);
  if (Array.isArray(parsed)) {
    return parsed.map(tag => String(tag).trim()).filter(Boolean).join(' ');
  }
  if (parsed && typeof parsed === 'object') {
    return Object.values(parsed).map(tag => String(tag).trim()).filter(Boolean).join(' ');
  }
  return String(parsed || '');
}

const row = $json;
const defaultShotDuration = Number(row.default_shot_duration || 5);
let shots = parseJsonLoose(row.shots_json, []);

if (!Array.isArray(shots) || shots.length === 0) {
  shots = fallbackShotsFromScript(row.script, defaultShotDuration);
}

shots = shots.map((shot, index) => ({
  shot_id: shot.shot_id || index + 1,
  duration: Math.max(2, Number(shot.duration || defaultShotDuration)),
  visual_prompt_cn: shot.visual_prompt_cn || shot.visual_prompt || shot.prompt || '',
  visual_prompt_en: shot.visual_prompt_en || '',
  subtitle: shot.subtitle || shot.text || ''
}));

return [
  {
    json: {
      task_id: String(row.id),
      topic: row.topic || '',
      title: row.title || row.topic || '未命名视频',
      hook: row.hook || '',
      script: row.script || '',
      cover_text: row.cover_text || row.title || row.topic || '短视频',
      hashtags: normalizeHashtags(row.hashtags),
      shots,
      options: {
        width: 1080,
        height: 1920,
        fps: 30,
        output_root: '/data/output',
        render_mode: 'placeholder_multishot',
        default_shot_duration: defaultShotDuration
      }
    }
  }
];

/**
 * n8n Code 节点：Parse Render Response Enhanced
 * 输入：HTTP Request - Render Multi-shot Video 返回的 JSON
 * 输出：给 Postgres - Update NEED_REVIEW 的字段
 */

const resp = $json;

if (!resp || resp.status !== 'ok') {
  throw new Error(`video-worker render failed: ${JSON.stringify(resp)}`);
}

const clips = Array.isArray(resp.clips) ? resp.clips : [];
const manifest = resp.manifest || resp;

return [
  {
    json: {
      task_id: String(resp.task_id || manifest.task_id || ''),
      video_path: resp.video_path || manifest.final_video || '',
      cover_path: resp.cover_path || manifest.cover_path || '',
      subtitle_path: resp.subtitle_path || manifest.subtitle_path || '',
      clips_json: JSON.stringify(clips),
      render_manifest: JSON.stringify(manifest),
      status: 'NEED_REVIEW'
    }
  }
];

/**
 * n8n Code node: Build Render Request TTS
 * Input: one row from PostgreSQL video_topics.
 * Output: JSON body for POST http://video-worker:8000/render
 */

const row = $json;

function parseJsonMaybe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return fallback;
  }
}

let shots = parseJsonMaybe(row.shots_json, []);
if (!Array.isArray(shots) || shots.length === 0) {
  shots = [
    {
      shot_id: 1,
      duration: Number(row.duration || 8),
      subtitle: row.hook || row.cover_text || row.title || row.topic,
      visual_prompt_cn: row.cover_text || row.title || row.topic,
    },
  ];
}

shots = shots.map((shot, index) => ({
  shot_id: shot.shot_id ?? index + 1,
  duration: Number(shot.duration || 5),
  subtitle: String(shot.subtitle || ''),
  visual_prompt_cn: String(shot.visual_prompt_cn || shot.prompt || shot.subtitle || ''),
  visual_prompt_en: String(shot.visual_prompt_en || ''),
}));

return [
  {
    json: {
      task_id: String(row.id),
      title: String(row.title || row.topic || 'AI 短视频'),
      script: String(row.script || row.hook || row.topic || ''),
      cover_text: String(row.cover_text || row.title || row.topic || ''),
      shots,
      width: 1080,
      height: 1920,
      fps: 30,
      enable_tts: true,
      // n8n inside Docker calls video-worker inside Docker.
      // video-worker then calls the host Mac's VoxCPM server through host.docker.internal.
      tts_base_url: 'http://host.docker.internal:8010',
